const incoming=$input.first().json;
const d=String(incoming?.data?.Decision??incoming?.Decision??incoming?.body?.Decision??'').trim();
const note=String(incoming?.data?.Commentaire??incoming?.Commentaire??incoming?.body?.Commentaire??'').trim().slice(0,2000);
const saved=$('Enregistrer le brouillon').first().json;
const rawId=saved?.id;
const text=typeof rawId==='string'?rawId.trim():typeof rawId==='number'&&Number.isSafeInteger(rawId)?String(rawId):'';
if(!/^(?:0*[1-9]\d*)$/.test(text))throw Error('brouillon_non_identifie');
const id=text.replace(/^0+/,'');
if(id.length>19||(id.length===19&&id>'9223372036854775807'))throw Error('brouillon_non_identifie');
const decision=d==='Approuver'?'approved':d==='Demander une modification'?'revision_requested':'rejected';
if(decision==='revision_requested'&&!note)throw Error('commentaire_requis_pour_modification');
return [{json:{id,decision,note}}];
